export function getDubaiProjectBySlug(slug) {
  if (!slug) return null;
  const clean = String(slug).toLowerCase().trim();
  return DUBAI_REGISTRY_PROJECTS.find(p => {
    return p.slug.toLowerCase() === clean || 
           String(p.id) === clean || 
           p.slug.replace(/-pid-\d+$/, '').toLowerCase() === clean ||
           p.name.toLowerCase().replace(/[^a-z0-9]+/g, '-') === clean;
  }) || null;
}

export const DUBAI_ALL_SLUGS = DUBAI_REGISTRY_PROJECTS.map(p => p.slug);

export const DUBAI_PROJECT_COORDINATES = Object.fromEntries(
  DUBAI_REGISTRY_PROJECTS.map(p => [
    p.slug,
    {
      lat: p.lat,
      lng: p.lng,
      locality: p.locality,
      region: p.region,
      city: "dubai",
      cityName: "Dubai",
      country: "United Arab Emirates",
      currency: "AED",
      propertyType: p.type || "Apartment",
      verified: true
    }
  ])
);
